from utils.retry import retry

def test_retry_helper_retries_and_raises_last_error():
    call_count = 0
    class CustomError(Exception):
        pass

    def failing_operation():
        nonlocal call_count
        call_count += 1
        if call_count < 3:
            raise ValueError("Attempt failed")
        else:
            raise CustomError("Last attempt failed")

    with pytest.raises(CustomError) as excinfo:
        retry(failing_operation, attempts=3)

    assert call_count == 3
    assert "Last attempt failed" in str(excinfo.value)",
